create table badge_scan_log (id bigint identity not null, active bit, created_at datetime2, created_by varchar(255), updated_at datetime2, updated_by varchar(255), failure_reason varchar(500), functionality varchar(255) not null, granted_by varchar(10), scan_type varchar(20) not null, scanned_badge_code varchar(50), session_id bigint, success bit not null, timestamp datetime2 not null, scanned_by_user_id bigint not null, scanned_user_id bigint, primary key (id));
